package mz.bam.seeky.android;
import java.util.*;
public class StudyTextTest {
 static int count;static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS "+s);count++;}
 public static void main(String[] a){StudyText d=new StudyText("Olá mundo. Outro mundo.");d.mark(4,9,"highlight","");d.mark(17,22,"note","rever");d.replace(0,3,"Bom");ok(d.marks.get(0).start==4,"edit before preserves offset");d.replace(0,0,"Oi ");ok(d.marks.get(0).start==7,"insert shifts annotations");d.replace(8,9,"");ok(d.marks.size()==1&&d.marks.get(0).note.equals("rever"),"overlapping edit removes only touched annotation");ok(StudyText.find("ÁGUA água", "água",10).equals(Arrays.asList(0,5)),"unicode case search offsets");ok(StudyText.find("aa aa aa","aa",2).size()==2,"search cap");ok(StudyText.find("a","",10).isEmpty(),"empty query");StudyText h=new StudyText("<a>\n&");h.mark(1,2,"highlight","");h.mark(1,2,"underline","");String html=h.html(0,h.text.length());ok(html.contains("&lt;")&&html.contains("&amp;")&&html.contains("<u>")&&html.contains("<mark"),"rich export escapes and formats");ok(!html.contains("<a>"),"no markup injection");StudyText c=new StudyText("abcdef");c.mark(4,6,"underline","");c.replace(1,3,"");ok(c.text.equals("adef")&&c.marks.get(0).start==2,"cut shifts later marks");try{c.replace(-1,2,"x");throw new AssertionError();}catch(IllegalArgumentException e){ok(true,"reject invalid selection");}c.replace(c.text.length(),c.text.length(),"!");ok(c.text.equals("adef!"),"append at end");System.out.println(count+" study checks");}
}
